from taf.internal.core import Factory
from .file_getter import CatFileGetter
from .file_putter import CatFilePutter
from taf.internal.execution.base import ExecutorFactory


class CatFileTransferFactory(Factory):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(CatFileTransferFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments['remote_executor'] = ExecutorFactory().create(
            configuration=configuration['executor'],
            existing_arguments={})
        resulting_arguments['local_executor'] = ExecutorFactory().create(
            configuration={'type': 'local'},
            existing_arguments={})


class CatFileGetterFactory(CatFileTransferFactory):
    _product_class = CatFileGetter


class CatFilePutterFactory(CatFileTransferFactory):
    _product_class = CatFilePutter
